From 9698693e6a9b9e126b3f0bb1a444529da8567792 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:04:40 +0100
Subject: [PATCH] applets/appmenu: Resize the menu when switching to another
 one

When the pointer moved to another menu while one was open, the popup was
only moved, so a long menu opened after a short one was cut off and could
not scroll. Show it again with popup(), which fits it to the new menu.

BUG: 523027
---
 applets/appmenu/appmenuapplet.cpp | 6 ++----
 1 file changed, 2 insertions(+), 4 deletions(-)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..3bd1022b30 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -233,14 +233,12 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)
                      qBound(geo.y(), pos.y(), geo.y() + geo.height() - m_currentMenu->height()));

         if (view() == FullView) {
-            if (m_currentMenu->isVisible()) {
-                m_currentMenu->move(pos);
-            } else {
+            if (!m_currentMenu->isVisible()) {
                 m_currentMenu->installEventFilter(this);
                 m_currentMenu->winId(); // create window handle
                 m_currentMenu->windowHandle()->setTransientParent(ctx->window());
-                m_currentMenu->popup(pos);
             }
+            m_currentMenu->popup(pos);
         } else if (view() == CompactView) {
             if (m_currentMenu->isEmpty()) {
                 // don't try to popup an empty menu in case the app gives us one
